	"portailfournisseur/view/fragment/NotificationPopover.fragment.xml":'<core:FragmentDefinition\n\txmlns="sap.m"\n\txmlns:core="sap.ui.core"><Popover\n\t\tid="notificationPopover"\n\t\ttitle="{i18n>notif.title}"\n\t\tplacement="Bottom"\n\t\tcontentWidth="24rem"\n\t\tcontentHeight="22rem"\n\t\tverticalScrolling="true"><customHeader><Bar><contentLeft><Title text="{i18n>notif.title}" level="H3"/></contentLeft><contentRight><Button\n\t\t\t\t\t\ttext="{i18n>notif.clear}"\n\t\t\t\t\t\ttype="Transparent"\n\t\t\t\t\t\tpress=".onClearNotifications"/></contentRight></Bar></customHeader><List\n\t\t\tid="notificationList"\n\t\t\titems="{data>/notifications}"\n\t\t\tnoDataText="{i18n>notif.empty}"\n\t\t\tshowSeparators="Inner"><StandardListItem\n\t\t\t\ticon="{path: \'data>sev\', formatter: \'.formatter.notificationIcon\'}"\n\t\t\t\ttitle="{parts: [\'data>title\', \'ui>/lang\'], formatter: \'.formatter.localized\'}"\n\t\t\t\tdescription="{parts: [\'data>desc\', \'ui>/lang\'], formatter: \'.formatter.localized\'}"\n\t\t\t\tinfo="{parts: [\'data>time\', \'ui>/lang\'], formatter: \'.formatter.localized\'}"\n\t\t\t\tinfoState="{path: \'data>sev\', formatter: \'.formatter.notificationState\'}"\n\t\t\t\ticonInset="false"\n\t\t\t\twrapping="true"/></List></Popover></core:FragmentDefinition>\n',
	"portailfournisseur/view/fragment/ShipmentDialog.fragment.xml":'<core:FragmentDefinition\n\txmlns="sap.m"\n\txmlns:core="sap.ui.core"\n\txmlns:form="sap.ui.layout.form"><Dialog\n\t\tid="shipmentDialog"\n\t\ttitle="{i18n>dialog.ship.title}"\n\t\tcontentWidth="32rem"\n\t\tdraggable="true"\n\t\tescapeHandler=".onCloseShipmentDialog"><content><VBox class="sapUiSmallMargin"><form:Form editable="true"><form:layout><form:ColumnLayout columnsM="1" columnsL="1" columnsXL="1"/></form:layout><form:formContainers><form:FormContainer><form:formElements><form:FormElement label="{i18n>dialog.ship.tracking}"><form:fields><Input\n\t\t\t\t\t\t\t\t\t\t\tid="shipTracking"\n\t\t\t\t\t\t\t\t\t\t\tvalue="{form>/tracking}"\n\t\t\t\t\t\t\t\t\t\t\tplaceholder="TRK-…"/></form:fields></form:FormElement><form:FormElement label="{i18n>dialog.ship.carrier}"><form:fields><Input\n\t\t\t\t\t\t\t\t\t\t\tid="shipCarrier"\n\t\t\t\t\t\t\t\t\t\t\tvalue="{form>/carrier}"\n\t\t\t\t\t\t\t\t\t\t\tplaceholder="Global Air Freight"/></form:fields></form:FormElement><form:FormElement label="{i18n>dialog.ship.date}"><form:fields><DatePicker\n\t\t\t\t\t\t\t\t\t\t\tid="shipDate"\n\t\t\t\t\t\t\t\t\t\t\tvalue="{form>/shipDate}"\n\t\t\t\t\t\t\t\t\t\t\tvalueFormat="yyyy-MM-dd"\n\t\t\t\t\t\t\t\t\t\t\tdisplayFormat="long"/></form:fields></form:FormElement><form:FormElement label="{i18n>dialog.ship.bl}"><form:fields><Button\n\t\t\t\t\t\t\t\t\t\t\ttext="{i18n>dialog.ship.uploadBtn}"\n\t\t\t\t\t\t\t\t\t\t\ticon="sap-icon://attachment"\n\t\t\t\t\t\t\t\t\t\t\tpress=".onDemoAction"/></form:fields></form:FormElement></form:formElements></form:FormContainer></form:formContainers></form:Form></VBox></content><beginButton><Button text="{i18n>dialog.cancel}" press=".onCloseShipmentDialog"/></beginButton><endButton><Button\n\t\t\t\ttext="{i18n>dialog.ship.submit}"\n\t\t\t\ttype="Emphasized"\n\t\t\t\tpress=".onSubmitShipment"/></endButton></Dialog></core:FragmentDefinition>\n',
	"portailfournisseur/view/fragment/UserPopover.fragment.xml":'<core:FragmentDefinition\n\txmlns="sap.m"\n\txmlns:core="sap.ui.core"><Popover\n\t\tid="userPopover"\n\t\tplacement="Bottom"\n\t\tcontentWidth="20rem"\n\t\tshowHeader="false"><VBox class="sapUiSmallMargin pfUserPopoverHeader"><Title\n\t\t\t\tlevel="H4"\n\t\t\t\ttext="{= ${ui>/persona} === \'supplier\' ? ${data>/context/personas/supplier/userName} : ${data>/context/personas/buyer/userName} }"/><Text\n\t\t\t\tclass="sapUiTinyMarginTop"\n\t\t\t\ttext="{path: \'ui>/persona\', formatter: \'.formatter.personaRoleText\'}"/></VBox><List showSeparators="None"><StandardListItem\n\t\t\t\ticon="sap-icon://building"\n\t\t\t\ttitle="{= ${ui>/persona} === \'supplier\' ? ${data>/context/personas/supplier/company} : ${data>/context/personas/buyer/company} }"\n\t\t\t\ttype="Inactive"/><StandardListItem\n\t\t\t\ticon="sap-icon://group"\n\t\t\t\ttitle="{i18n>nav.adminLong}"\n\t\t\t\ttype="Active"\n\t\t\t\tvisible="{= ${ui>/persona} === \'supplier\' }"\n\t\t\t\tpress=".onUserMenuAdmin"/><StandardListItem\n\t\t\t\ticon="sap-icon://action-settings"\n\t\t\t\ttitle="{i18n>user.settings}"\n\t\t\t\ttype="Active"\n\t\t\t\tpress=".onUserMenuDemo"/><StandardListItem\n\t\t\t\ticon="sap-icon://log"\n\t\t\t\ttitle="{i18n>user.logout}"\n\t\t\t\ttype="Active"\n\t\t\t\tpress=".onUserMenuDemo"/></List></Popover></core:FragmentDefinition>\n',
